function f(c,r,e,i){const s=Number(c),t=Number(r),n=Number(e),u=Number(i);if([s,t,n,u].some(o=>o==null||Number.isNaN(o)))return 1/0;const M=6371e3,a=o=>o*Math.PI/180,h=a(n-s),N=a(u-t),b=Math.sin(h/2)**2+Math.cos(a(s))*Math.cos(a(n))*Math.sin(N/2)**2;return M*2*Math.atan2(Math.sqrt(b),Math.sqrt(1-b))}const m=f;function l(c,r,e,i=500){if(!r||!e)return[];const s=[];for(const t of c){if(!t.lat||!t.lng)continue;const n=f(r,e,Number(t.lat),Number(t.lng));n<=i&&s.push({...t,_nearbyDist:Math.round(n)})}return s.sort((t,n)=>t._nearbyDist-n._nearbyDist)}export{l as f,m as g};
